typedef struct {char key[32],text[129];int type;} field;
static void ws(const char**p){while(isspace((unsigned char)**p))(*p)++;}
static int string(const char**p,char*out,size_t cap){size_t n=0;if(*(*p)++!='"')return -1;while(**p&&**p!='"'){unsigned char c=(unsigned char)*(*p)++;if(c=='\\'){c=(unsigned char)*(*p)++;switch(c){case '"':case '\\':case '/':break;case 'b':c='\b';break;case 'f':c='\f';break;case 'n':c='\n';break;case 'r':c='\r';break;case 't':c='\t';break;default:return -1;}}else if(c<32||c>126)return -1;if(n+1>=cap)return -1;out[n++]=(char)c;}if(**p!='"')return -1;(*p)++;out[n]=0;return 0;}
static int parse(const char*p,field*f){int n=0,i;ws(&p);if(*p++!='{')return -1;ws(&p);if(*p=='}'){p++;ws(&p);return *p?-1:0;}while(n<20){const char*s;size_t z;if(string(&p,f[n].key,sizeof(f[n].key)))return -1;for(i=0;i<n;i++)if(!strcmp(f[i].key,f[n].key))return -1;ws(&p);if(*p++!=':')return -1;ws(&p);if(*p=='"'){f[n].type=1;if(string(&p,f[n].text,sizeof(f[n].text)))return -1;}else if(!strncmp(p,"true",4)||!strncmp(p,"false",5)){f[n].type=3;z=*p=='t'?4:5;memcpy(f[n].text,p,z);f[n].text[z]=0;p+=z;}else{f[n].type=2;s=p;while(isdigit((unsigned char)*p))p++;z=(size_t)(p-s);if(!z||z>20||(z>1&&*s=='0'))return -1;memcpy(f[n].text,s,z);f[n].text[z]=0;}n++;ws(&p);if(*p=='}'){p++;ws(&p);return *p?-1:n;}if(*p++!=',')return -1;ws(&p);}return -1;}
static field*get(field*f,int n,const char*key){int i;for(i=0;i<n;i++)if(!strcmp(f[i].key,key))return f+i;return NULL;}
static const char*str(field*f,int n,const char*key){field*v=get(f,n,key);return v&&v->type==1?v->text:NULL;}
static int number(field*f,int n,const char*key,uint32_t*x){field*v=get(f,n,key);unsigned long long z;char*e;if(!v||v->type!=2)return -1;errno=0;z=strtoull(v->text,&e,10);if(errno||*e||z>UINT32_MAX)return -1;*x=(uint32_t)z;return 0;}
static int safe(const char*s){size_t n=0;if(!s)return 0;for(;*s;s++,n++)if(!(isalnum((unsigned char)*s)||strchr("_.:-",*s)))return 0;return n>=1&&n<=48;}
void ann_id_text(ann_id id,char out[18]){snprintf(out,18,"%02x:%02x:%02x:%02x:%02x:%02x",(unsigned)((id>>40)&255),(unsigned)((id>>32)&255),(unsigned)((id>>24)&255),(unsigned)((id>>16)&255),(unsigned)((id>>8)&255),(unsigned)(id&255));}
int ann_id_parse(const char*s,ann_id*id){unsigned i;uint64_t x=0;if(!s||strlen(s)!=17)return -1;for(i=0;i<17;i++){unsigned v;char c=s[i];if(i%3==2){if(c!=':')return -1;continue;}if(c>='0'&&c<='9')v=c-'0';else if(c>='a'&&c<='f')v=c-'a'+10;else if(c>='A'&&c<='F')v=c-'A'+10;else return -1;x=(x<<4)|v;}if(!x)return -1;*id=x;return 0;}
void ann_console_init(ann_console*c,ann_node*n,const char*chip,const char*build){memset(c,0,sizeof(*c));c->node=n;c->chip=chip;c->build_id=build;}
int ann_command(ann_console*c,const char*input,size_t len,char*out,size_t cap,uint64_t now){field f[20];char line[513],id[18];int n,ok=0;const char*nonce=NULL,*cmd=NULL,*error="invalid_json",*allowed=NULL;const char*run;uint32_t duration,count,interval,frame;ann_id dst;field*echo;int i;char nonce_json[55]="null";ann_id_text(c->node->id,id);
 if(!input||len>512||memchr(input,0,len))goto reply;memcpy(line,input,len);line[len]=0;n=parse(line,f);if(n<0)goto reply;nonce=str(f,n,"nonce");if(!safe(nonce)){error="invalid_nonce";goto reply;}snprintf(nonce_json,sizeof(nonce_json),"\"%s\"",nonce);cmd=str(f,n,"cmd");if(!cmd){error="invalid_command";goto reply;}
 if(!strcmp(cmd,"info")||!strcmp(cmd,"stats")||!strcmp(cmd,"stop"))allowed=" cmd nonce ";else if(!strcmp(cmd,"arm"))allowed=" cmd nonce node_id run_id duration_ms ";else if(!strcmp(cmd,"start"))allowed=" cmd nonce run_id ";else if(!strcmp(cmd,"bench"))allowed=" cmd nonce run_id dst count interval_ms frame_bytes echo ";else{error="unknown_command";goto reply;}
 for(i=0;i<n;i++){char name[36];snprintf(name,sizeof(name)," %s ",f[i].key);if(!strstr(allowed,name)){error="unknown_field";goto reply;}}
 if(!strcmp(cmd,"info")){int z=snprintf(out,cap,"{\"schema\":\"ann.serial.v1\",\"event\":\"info\",\"nonce\":%s,\"ok\":true,\"firmware\":\"ann-espnow\",\"protocol\":1,\"node_id\":\"%s\",\"boot_id\":\"%08lx\",\"build_id\":\"%s\",\"chip\":\"%s\",\"board\":\"unverified\",\"mode\":\"%s\"}",nonce_json,id,(unsigned long)c->node->boot,c->build_id,c->chip,c->node->active?"active":"idle");return z>=0&&(size_t)z<cap?0:-1;}
 if(!strcmp(cmd,"stats")){int z=snprintf(out,cap,"{\"schema\":\"ann.serial.v1\",\"event\":\"stats\",\"nonce\":%s,\"ok\":true,\"run_id\":%s%s%s,\"node_id\":\"%s\",\"boot_id\":\"%08lx\",\"origin_id\":null,\"seq\":null,\"t_us\":%llu,\"frame_bytes\":null,\"payload_bytes\":null,\"delivered\":%lu,\"confirmed\":%lu,\"duplicates\":%lu,\"queue_overflow\":%lu,\"event_overflow\":%lu,\"airtime_us\":null,\"rf_retries\":null,\"pdr\":null,\"rtt_p95_ms\":null}",nonce_json,c->run_id[0]?"\"":"",c->run_id[0]?c->run_id:"null",c->run_id[0]?"\"":"",id,(unsigned long)c->node->boot,(unsigned long long)(now*1000),(unsigned long)c->node->delivered,(unsigned long)c->node->confirmed,(unsigned long)c->node->duplicates,(unsigned long)c->node->queue_overflow,(unsigned long)c->node->event_overflow);return z>=0&&(size_t)z<cap?0:-1;}
 if(!strcmp(cmd,"stop")){ann_stop(c->node,now);c->armed=0;c->bench=0;ok=1;goto reply;}
 run=str(f,n,"run_id");if(!safe(run)){error="invalid_run_id";goto reply;}
 if(!strcmp(cmd,"arm")){if(c->node->active||c->bench){error="stop_before_arm";goto reply;}if(!str(f,n,"node_id")||strcmp(str(f,n,"node_id"),id)||number(f,n,"duration_ms",&duration)||!duration||duration>60000){error="invalid_binding_or_duration";goto reply;}c->armed=1;c->arm_until=now+duration;strcpy(c->run_id,run);ok=1;goto reply;}
 if(!c->armed||now>=c->arm_until||strcmp(run,c->run_id)){error="not_armed";goto reply;}
 if(!strcmp(cmd,"start")){ann_start(c->node,now);ok=1;goto reply;}
 echo=get(f,n,"echo");if(number(f,n,"count",&count)||number(f,n,"interval_ms",&interval)||number(f,n,"frame_bytes",&frame)||!count||count>1000||!interval||interval>60000||frame<112||frame>250||!echo||echo->type!=3||ann_id_parse(str(f,n,"dst"),&dst)||dst==c->node->id||(uint64_t)(count-1)*interval>60000||(uint64_t)(count-1)*interval>=c->arm_until-now){error="invalid_bench_bounds";goto reply;}
 if(!strcmp(echo->text,"true")&&frame<120){error="echo_needs_8_payload_bytes";goto reply;}
 if(c->bench){error="bench_already_running";goto reply;}c->bench=1;c->dst=dst;c->count=count;c->sent=0;c->interval=interval;c->frame_bytes=frame;c->echo=!strcmp(echo->text,"true");c->next=now;c->duration_end=c->arm_until;ann_start(c->node,now);ok=1;
 reply:{int z=snprintf(out,cap,"{\"schema\":\"ann.serial.v1\",\"event\":\"%s\",\"nonce\":%s,\"ok\":%s%s%s%s}",ok?cmd:"error",nonce_json,ok?"true":"false",ok?"":",\"error\":\"",ok?"":error,ok?"":"\"");return z>=0&&(size_t)z<cap?(ok?0:-1):-1;}
}
void ann_console_tick(ann_console*c,uint64_t now){uint8_t data[138];uint32_t seq;if(c->armed&&now>=c->arm_until){ann_stop(c->node,now);c->bench=0;c->armed=0;return;}ann_tick(c->node,now);if(!c->bench)return;if(now>=c->duration_end){ann_stop(c->node,now);c->bench=0;c->armed=0;return;}if(c->sent<c->count&&now>=c->next){memset(data,(int)(c->sent&255),sizeof(data));if(!ann_submit(c->node,c->dst,ANN_TRANSACTION,0,data,c->frame_bytes-112,(uint32_t)(c->duration_end-now),c->echo?1:0,now,&seq)){c->sent++;c->next=now+c->interval;}else c->next=now+c->interval;}}
